  --room: #2b1f27;
  --room-light: #3b2b35;
  --room-deep: #1c1318;
  --lamp: #f4eadb;
  --lamp-bright: #f9f2e6;
  --lamp-deep: #e6d8c3;
  --ink: #2a1e23;
  --ink-2: #6f6066;
  --ink-3: #9d8f95;
  --on-room: #f4eadb;
  --on-room-2: rgba(244, 234, 219, 0.64);
  --on-room-3: rgba(244, 234, 219, 0.38);
  --veil: rgba(244, 234, 219, 0.08);
  --veil-2: rgba(244, 234, 219, 0.14);
  --chili: #d8412f;
  --chili-deep: #b7321f;
  --p1: #d98c9b;
  --p2: #e0a472;
  --p3: #9db58b;
  --p4: #8dafc7;
  --p5: #b39ac9;
  --p6: #d2b15a;
  --p7: #7fb3ae;
  --p8: #c98a78;
  --r-card: 28px;
  --r-control: 14px;
  --shadow-card:
    0 34px 60px -24px rgba(0, 0, 0, 0.6),
    0 0 110px -20px rgba(244, 234, 219, 0.14);
  --shadow-soft: 0 14px 30px -18px rgba(0, 0, 0, 0.5);
  color-scheme: dark;
}

* {
  box-sizing: border-box;
}

html {
  background: var(--room-deep);
}

body {
  margin: 0;
  min-height: 100dvh;
  color: var(--on-room);
  background:
    radial-gradient(ellipse 130% 60% at 50% -12%, var(--room-light) 0%, var(--room) 48%, var(--room-deep) 100%)
      fixed;
  font-family: var(--font-body), "Segoe UI", sans-serif;
  font-size: 1rem;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

h1,
h2,
h3 {
  margin: 0;
  font-family: var(--font-display), Georgia, serif;
  font-weight: 400;
  letter-spacing: -0.01em;
}

p {
  margin: 0;
}

button,
input {
  font: inherit;
  color: inherit;
}

button {
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

button:disabled {
  cursor: default;
  opacity: 0.55;
}

a {
  color: inherit;
  -webkit-tap-highlight-color: transparent;
}

:focus-visible {
  outline: 2px solid var(--lamp);
  outline-offset: 3px;
}

.card :focus-visible,
.card-front :focus-visible {
  outline-color: var(--chili);
}

/* Shell */

.shell {
  width: min(440px, 100%);
  min-height: 100dvh;
  margin: 0 auto;
  padding: 0 16px calc(20px + env(safe-area-inset-bottom));
  display: flex;
  flex-direction: column;
}

.topbar {
  height: 64px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: var(--veil-2);
  overflow: hidden;
  margin: 0 4px 22px;
}

.progress span {
  display: block;
  height: 100%;
  border-radius: 2px;
  background: var(--lamp);
  transition: width 0.3s ease;
}

.stage {
  position: relative;
  display: grid;
  flex: 1;
  min-height: 460px;
}

.card {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  padding: 26px 24px 22px;
  border-radius: var(--r-card);
  background:
    radial-gradient(ellipse 90% 50% at 50% 0%, var(--lamp-bright) 0%, transparent 70%),
    linear-gradient(180deg, var(--lamp) 0%, var(--lamp-deep) 100%);
  color: var(--ink);
  box-shadow: var(--shadow-card);
  overflow: hidden;
}

.card.behind {
  transform: scale(0.94) translateY(26px);
  opacity: 0.6;
  box-shadow: none;
}

.card.front {
  position: relative;
  inset: auto;
  min-width: 0;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
  cursor: grab;
  transition: transform 0.25s ease;
}

.card.front.dragging {
  cursor: grabbing;
  transition: none;
}

.restaurant-photo {
  margin: 0 0 18px;
}

.restaurant-photo img {
  display: block;
  width: 100%;
  height: auto;
  aspect-ratio: 16 / 9;
  color: var(--on-room-2);
}

.handoff h1 {
  font-size: clamp(2.6rem, 12vw, 3.4rem);
  line-height: 1.05;
  margin: 6px 0 30px;
}

.handoff .step-nav {
  margin-top: 36px;
}

/* Result and fallback */

.panel {
  padding: 26px 24px 24px;
  border-radius: var(--r-card);
  background:
    radial-gradient(ellipse 90% 50% at 50% 0%, var(--lamp-bright) 0%, transparent 70%),
    linear-gradient(180deg, var(--lamp) 0%, var(--lamp-deep) 100%);
  color: var(--ink);
  box-shadow: var(--shadow-card);
}

.panel .lead {
  color: var(--ink-2);
  font-size: 0.95rem;
}

.panel h2 {
  margin: 10px 0 14px;
  font-size: clamp(2rem, 9vw, 2.5rem);
  line-height: 1.05;
}

.supporters {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 12px;

